(async()=>{
window.audit={results:[]};
const studio=(await import('/src/studio/store.ts')).useStudio;
const api=await import('/src/studio/assistant/session.ts');
const session=await api.getAssistantMcp(), id=studio.getState().job.id;
const bound={expectedJobId:id};
async function call(name,args,expected='success'){
 let result;
 try{result=await api.callAssistantTool(name,args,AbortSignal.timeout(90000),{allowProjectEdits:true});}
 catch(e){result={isError:true,content:[{type:'text',text:e.message}]};}
 const text=result.content.filter(c=>c.type==='text').map(c=>c.text).join('\n');
 const record={name,args,expected,isError:!!result.isError,text,images:result.content.filter(c=>c.type==='image').map(c=>({mimeType:c.mimeType,bytes:c.data.length}))};audit.results.push(record);
 if(expected==='success' && result.isError)throw Error(name+': '+text);
 if(expected==='refusal' && !result.isError)throw Error(name+' accepted invalid input');
 try{return JSON.parse(text)}catch{return text}
}
audit.call=call;audit.store=studio;audit.id=id;
for(const t of session.tools) await call(t.name,{unexpectedAuditArgument:true},'refusal');
for(const name of ['read_project_context','read_workbench_structure'])await call(name,{});
for(const name of ['read_assistant_file','read_source_sheets','read_takeoff_evidence','read_price_books','read_work_packet'])await call(name,bound);
await call('read_workflow_route',{...bound,workflow:'architecture'});
await call('navigate_workspace',{...bound,pane:'sketch'});
async function rendered(revision){await new Promise((resolve,reject)=>{const end=performance.now()+5000;function check(){if(Number(document.querySelector('[data-design-revision]')?.dataset.designRevision)===revision)return resolve();if(performance.now()>end)return reject(Error('Design render deadline'));requestAnimationFrame(check)}check()})}
let design=(await call('read_architect_design',bound)).project;await rendered(design.revision);
await call('draw_architect_elements',{...bound,expectedRevision:design.revision,operations:[{kind:'footprint',levelId:design.levels[0].id,points:[[0,0],[6000,0],[6000,4000],[0,4000]],name:'Audit room'}]});
design=(await call('read_architect_design',bound)).project;await rendered(design.revision);
if(design.walls.length!==4)throw Error('Expected four walls');
await call('edit_architect_elements',{...bound,expectedRevision:design.revision,operations:[{kind:'rename-design',name:'Audit renamed'}]});
design=(await call('read_architect_design',bound)).project;await rendered(design.revision);
if(design.name!=='Audit renamed')throw Error('Rename readback failed');
await call('undo_architect_change',{...bound,expectedRevision:design.revision});
design=(await call('read_architect_design',bound)).project;await rendered(design.revision);
if(design.name==='Audit renamed'||design.walls.length!==4)throw Error('Undo readback failed');
await call('save_project',{...bound,expectedRevision:studio.getState().job.revision});
await call('capture_project_backup',{...bound,expectedRevision:studio.getState().job.revision,name:'Tool audit fixture'});
await call('export_design_file',{...bound,expectedRevision:design.revision,format:'dxf'});
const books=await call('read_price_books',bound);
await call('import_price_book',{...bound,expectedLibraryRevision:books.libraryRevision,bookName:'Audit fictional rates',csvText:'description,unit,rate\nAudit stud,m,5.50',mapping:{stockCode:null,description:0,unit:1,rate:2},metadata:{supplier:'Audit fixture - fictional',currency:'AUD',taxBasis:'exclusive',effectiveDate:'2026-09-10',sourceReference:'Synthetic tool test; never a supplier quote'}});
const readback=await call('read_price_books',bound);
await call('show_design_in_model',{...bound,expectedRevision:design.revision,displayMode:'solid'});
await call('read_source_building',{...bound,building:(await import('/src/studio/architect/designedScene.ts')).DESIGNED_SCENE_ID});
await call('read_draftsman_status',bound);
await call('control_draftsman',{...bound,action:'play'});
await call('control_draftsman',{...bound,action:'pause'});
await call('control_draftsman',{...bound,action:'exit'});
await call('capture_workspace_image',{...bound,target:'source-building'});
return {discovered:session.tools.map(t=>t.name),results:audit.results,design:{revision:design.revision,walls:design.walls},priceBooks:readback};
})()
